#include <iostream>
#include <iomanip>

int main() {
    // Đọc liên tục các số thực từ stdin cho đến khi gặp EOF
    // Có thể chạy trực tiếp với chuyển hướng: app < input.txt hoặc generator | app
    double value = 0.0;
    double sum = 0.0;
    std::size_t count = 0;

    while (std::cin >> value) {
        sum += value;
        ++count;
    }

    std::cout << "Count: " << count << "\n";
    if (count > 0) {
        std::cout << std::fixed << std::setprecision(2);
        std::cout << "Sum: " << sum << "\n";
        std::cout << "Average: " << (sum / count) << "\n";
    } else {
        std::cout << "No input provided.\n";
    }
    return 0;
}

#include <iostream>
#include <iomanip>

// Giải pháp C++17: Variadic Template kết hợp Fold Expression
// Thay thế hoàn toàn cơ chế va_list/va_arg/va_end bằng mã an toàn kiểu tại compile-time
template <typename First, typename... Rest>
double calculate_average(First first, Rest... rest) {
    constexpr std::size_t total_count = 1 + sizeof...(rest);
    double sum = static_cast<double>(first) + (static_cast<double>(rest) + ...);
    return sum / total_count;
}

int main() {
    double w = 37.5;
    double x = 22.5;
    double y = 1.7;
    double z = 10.2;

    std::cout << std::fixed << std::setprecision(1);
    std::cout << "w = " << w << "\n";
    std::cout << "x = " << x << "\n";
    std::cout << "y = " << y << "\n";
    std::cout << "z = " << z << "\n\n";

    std::cout << std::setprecision(3);
    std::cout << "The average of w and x is " 
              << calculate_average(w, x) << "\n";
    std::cout << "The average of w, x, and y is " 
              << calculate_average(w, x, y) << "\n";
    std::cout << "The average of w, x, y, and z is " 
              << calculate_average(w, x, y, z) << "\n";

    return 0;
}
